schema:
CREATE TABLE R1 (
    A INT,
    B INT
);
CREATE TABLE R2 (
    A INT,
    B INT,
    PRIMARY KEY (A)
);

CREATE TABLE ITP (
    ITEMNO INT,
    NP INT
);
CREATE TABLE ITM (
    ITEMNO INT,
    TYPE INT,
    PRIMARY KEY (ITEMNO)
);

counterexample:
INSERT INTO ITP (ITEMNO, NP) VALUES (1, 1500);
INSERT INTO ITP (ITEMNO, NP) VALUES (1, 1500);

INSERT INTO ITM (ITEMNO, TYPE) VALUES (1, 10);

-- When executing Q1:
--   The subquery [SELECT DISTINCT ITEMNO AS ITN, NP FROM ITP WHERE NP > 1000] returns one row: (1,1500).
--   Joining with ITM yields a single result row: (1500,10,1).

-- When executing Q2:
--   The join [FROM ITP, ITM WHERE NP > 1000 AND ITP.ITEMNO = ITM.ITEMNO] produces two rows (both (1500,10,1)) because there are two ITP rows.
--   Even though the outer DISTINCT then eliminates the duplicate and the final result set is the same, the intermediate (multiset) behavior is different.

-- This counterexample shows that Q1 and Q2 do not behave identically in all contexts (for example, if the duplicate‐removal were done later, aggregates like COUNT(*) would differ).

