CREATE TABLE MONTHS (MID INT, MONTH INT);
CREATE TABLE WEEKDAYS (DID INT, DAY_OF_WEEK INT);
CREATE TABLE CARRIERS (CID INT, NAME INT);
CREATE TABLE FLIGHTS (FID INT, ORIGIN_CITY INT, DEST_CITY INT, ACTUAL_TIME INT);

counterexample:
INSERT INTO FLIGHTS (FID, ORIGIN_CITY, DEST_CITY, ACTUAL_TIME) VALUES (1, 1, 10, 100);
INSERT INTO FLIGHTS (FID, ORIGIN_CITY, DEST_CITY, ACTUAL_TIME) VALUES (2, 1, 20, 100);
-- Duplicate maximum flight; note that even though FID is different, the displayed columns match
INSERT INTO FLIGHTS (FID, ORIGIN_CITY, DEST_CITY, ACTUAL_TIME) VALUES (3, 1, 20, 100);
-- A non-maximum flight
INSERT INTO FLIGHTS (FID, ORIGIN_CITY, DEST_CITY, ACTUAL_TIME) VALUES (4, 1, 30, 90);

