schema:
CREATE TABLE COURSE (COURSE_ID INT, TITLE INT, DEPT_NAME INT, CREDITS INT);
CREATE TABLE DEPARTMENT (DEPT_NAME INT, BUILDING INT, BUDGET INT);
CREATE TABLE INSTRUCTOR (ID INT, NAME INT, SALARY INT, DEPT_NAME INT);
CREATE TABLE TEACHES (ID INT, COURSE_ID INT, SEC_ID INT, YEAR INT, SEMESTER INT, INSTRUCTOR INT);
CREATE TABLE SECTION (COURSE_ID INT, SEC_ID INT, YEAR INT, BUILDING INT, ROOM_NUMBER INT, TIME_SLOT_ID INT);
CREATE TABLE TAKES (ID INT, COURSE_ID INT, SEC_ID INT, YEAR INT, GRADE INT);
CREATE TABLE STUDENT (ID INT, NAME INT, DEPT_NAME INT, TOT_CRED INT);

counterexample:
-- Insert data into STUDENT table
INSERT INTO STUDENT (ID, NAME, DEPT_NAME, TOT_CRED) VALUES (1, 'Alice', 'CS', 10);
INSERT INTO STUDENT (ID, NAME, DEPT_NAME, TOT_CRED) VALUES (2, 'Bob', 'Math', 10);
INSERT INTO STUDENT (ID, NAME, DEPT_NAME, TOT_CRED) VALUES (3, 'Charlie', 'EE', 10);

-- Insert data into TAKES table
-- Student 1: two courses that, when joined to SECTION, will have TIME_SLOT_ID = 0
INSERT INTO TAKES (ID, COURSE_ID, SEC_ID, YEAR, GRADE) VALUES (1, 101, 1, 2020, 90);
INSERT INTO TAKES (ID, COURSE_ID, SEC_ID, YEAR, GRADE) VALUES (1, 102, 1, 2020, 85);

-- Student 2: two courses with TIME_SLOT_ID = 1
INSERT INTO TAKES (ID, COURSE_ID, SEC_ID, YEAR, GRADE) VALUES (2, 103, 1, 2020, 80);
INSERT INTO TAKES (ID, COURSE_ID, SEC_ID, YEAR, GRADE) VALUES (2, 104, 1, 2020, 75);

-- Student 3: two courses with TIME_SLOT_ID = 1
INSERT INTO TAKES (ID, COURSE_ID, SEC_ID, YEAR, GRADE) VALUES (3, 105, 1, 2020, 70);
INSERT INTO TAKES (ID, COURSE_ID, SEC_ID, YEAR, GRADE) VALUES (3, 106, 1, 2020, 65);

-- Insert data into SECTION table
-- For student 1, both sections report TIME_SLOT_ID = 0 so that COUNT > 1 holds but SUM is 0
INSERT INTO SECTION (COURSE_ID, SEC_ID, YEAR, BUILDING, ROOM_NUMBER, TIME_SLOT_ID) VALUES (101, 1, 2020, 'B1', 101, 0);
INSERT INTO SECTION (COURSE_ID, SEC_ID, YEAR, BUILDING, ROOM_NUMBER, TIME_SLOT_ID) VALUES (102, 1, 2020, 'B1', 102, 0);

-- For student 2, sections with TIME_SLOT_ID = 1 (so count=2 and sum=2, both > 1)
INSERT INTO SECTION (COURSE_ID, SEC_ID, YEAR, BUILDING, ROOM_NUMBER, TIME_SLOT_ID) VALUES (103, 1, 2020, 'B2', 201, 1);
INSERT INTO SECTION (COURSE_ID, SEC_ID, YEAR, BUILDING, ROOM_NUMBER, TIME_SLOT_ID) VALUES (104, 1, 2020, 'B2', 202, 1);

-- For student 3, sections with TIME_SLOT_ID = 1
INSERT INTO SECTION (COURSE_ID, SEC_ID, YEAR, BUILDING, ROOM_NUMBER, TIME_SLOT_ID) VALUES (105, 1, 2020, 'B3', 301, 1);
INSERT INTO SECTION (COURSE_ID, SEC_ID, YEAR, BUILDING, ROOM_NUMBER, TIME_SLOT_ID) VALUES (106, 1, 2020, 'B3', 302, 1);

